function Notifications(){const {success,go}=useApp();const {data,error}=useData('/notifications');const [filter,setFilter]=useState(false),[actionError,setActionError]=useState('');if(error)return <ErrorBox error={error}/>;if(!data)return <Loading/>;return <><Header title="الإشعارات" subtitle={`${num(data.filter(n=>!n.read_at).length)} إشعار غير مقروء`}><button className="secondary" onClick={async()=>{try{await api('/notifications/read',{method:'POST',body:{}});success('تم تعليم الإشعارات كمقروءة');}catch(e){setActionError(e.message);}}}><CheckCheck size={17}/>تعليم الكل كمقروء</button></Header><ErrorBox error={actionError}/><div className="tabs"><button className={!filter?'selected':''} onClick={()=>setFilter(false)}>الكل</button><button className={filter?'selected':''} onClick={()=>setFilter(true)}>غير مقروء</button></div><section className="panel notification-list">{data.filter(n=>!filter||!n.read_at).map(n=><button className={'notification '+(!n.read_at?'unread':'')} key={n.id} onClick={async()=>{try{await api('/notifications/read',{method:'POST',body:{id:n.id}});success('تمت قراءة الإشعار');go(n.link);}catch(e){setActionError(e.message);}}}><span className="notification-icon"><Bell size={21}/></span><div><b>{n.title}</b><p>{n.body}</p><small>{fmt(n.created_at)}</small></div>{!n.read_at&&<span className="unread-dot"/>}<ChevronLeft size={18}/></button>)}{!data.filter(n=>!filter||!n.read_at).length&&<Empty text="لا توجد إشعارات"/>}</section></>;}
function UserManagement(){const {success}=useApp();const {data,error}=useData('/users');const [tab,setTab]=useState('users'),[edit,setEdit]=useState(null);if(error)return <ErrorBox error={error}/>;if(!data)return <Loading/>;return <><Header title="المستخدمون والصلاحيات" subtitle="إدارة الحسابات وتحديد ما يمكن لكل دور الوصول إليه">{tab==='users'&&<button className="primary" onClick={()=>setEdit({})}><Plus size={18}/>إضافة حساب</button>}</Header><div className="tabs"><button className={tab==='users'?'selected':''} onClick={()=>setTab('users')}>المستخدمون</button><button className={tab==='roles'?'selected':''} onClick={()=>setTab('roles')}>الأدوار والصلاحيات</button><button className={tab==='departments'?'selected':''} onClick={()=>setTab('departments')}>الأقسام ومسؤولوها</button></div>{tab==='users'?<section className="panel"><Table rows={data.users} columns={[["name","الموظف",r=><Person row={r}/>],['username','اسم المستخدم'],['role','الدور',r=>data.roles.find(x=>x.code===r.role)?.label],['active','الحالة',r=><Status value={r.active?'ACTIVE':'INACTIVE'}/>],['edit','الإدارة',r=><button className="text-button" onClick={()=>setEdit(r)}>تعديل الحساب</button>]]}/></section>:tab==='departments'?<Departments/>:<div className="role-grid">{data.roles.map(role=><RoleCard key={role.code+role.permissions.join()} role={role} labels={data.permissionLabels}/>)}</div>}{edit&&<Modal title={edit.id?'تعديل الحساب':'إضافة حساب'} onClose={()=>setEdit(null)}><Form onClose={()=>setEdit(null)} onSubmit={async f=>{const b=Object.fromEntries(f);if(edit.id){b.active=b.active==='true';if(!b.password)delete b.password;}else b.employee_id=Number(b.employee_id);await api('/users'+(edit.id?'/'+edit.id:''),{method:edit.id?'PUT':'POST',body:b});success();setEdit(null);}}>{edit.id?<p>{edit.name} · {edit.username}</p>:<><EmployeeSelect/><Input label="اسم المستخدم (أحرف إنجليزية صغيرة)" name="username" pattern="[a-z0-9._-]{3,50}" required dir="ltr"/></>}<Select label="الدور" name="role" defaultValue={edit.role||'EMPLOYEE'} options={data.roles.map(r=>[r.code,r.label])}/>{edit.id&&<Select label="حالة الحساب" name="active" defaultValue={String(edit.active)} options={[["true","نشط"],["false","معطل"]]}/>}<Input label={edit.id?'كلمة مرور جديدة (اتركها فارغة للإبقاء عليها)':'كلمة المرور — 12 حرفًا على الأقل'} name="password" type="password" minLength={12} maxLength={128} required={!edit.id} autoComplete="new-password"/><p className="muted">تعديل الحساب ينهي جلساته الحالية، ويتطلب تسجيل الدخول مجددًا.</p></Form></Modal>}</>;}
function Departments(){const {success}=useApp();const {data:meta,error}=useData('/meta'),{data:people}=useData('/employees');const [edit,setEdit]=useState(null);if(error)return <ErrorBox error={error}/>;if(!meta||!people)return <Loading/>;return <><div className="toolbar"><button className="secondary" onClick={()=>setEdit({})}><Plus size={17}/>إضافة قسم</button></div><section className="panel"><Table rows={meta.departments} columns={[["name","القسم"],["manager_id","مسؤول الموافقات",r=>people.find(p=>p.id===r.manager_id)?.name||'إحالة إلى HR'],['edit','الإدارة',r=><button className="text-button" onClick={()=>setEdit(r)}>تعديل</button>]]}/></section>{edit&&<Modal title={edit.id?'تعديل القسم':'إضافة قسم'} onClose={()=>setEdit(null)}><Form onClose={()=>setEdit(null)} onSubmit={async f=>{const b={name:f.get('name')};if(edit.id)b.manager_id=f.get('manager_id')?Number(f.get('manager_id')):null;await api('/departments'+(edit.id?'/'+edit.id:''),{method:edit.id?'PUT':'POST',body:b});success();setEdit(null);}}><Input label="اسم القسم" name="name" defaultValue={edit.name} required/>{edit.id&&<Select label="مسؤول القسم" name="manager_id" defaultValue={edit.manager_id||''} options={[["","بدون مسؤول — إحالة إلى HR"],...people.filter(p=>p.department_id===edit.id).map(p=>[p.id,p.name])]}/>}<div className="info-note">يتطلب تعيين المسؤول حسابًا نشطًا وصلاحية «موافقة مسؤول القسم». عند إزالة المسؤول تُحال طلبات القسم المعلقة إلى HR.</div></Form></Modal>}</>;}
function RoleCard({role,labels}){const {success}=useApp();const [permissions,setPermissions]=useState(role.permissions),[error,setError]=useState(''),[busy,setBusy]=useState(false);return <section className="panel role-card"><h3>{role.label}</h3><small className="role-code">{role.code}</small><p className="muted">الخدمة الذاتية متاحة لكل حساب؛ الصلاحيات التالية توسّع نطاق الوصول.</p><ErrorBox error={error}/><div className="permission-list">{Object.entries(labels).map(([k,label])=><label key={k}><input type="checkbox" checked={permissions.includes(k)} onChange={e=>setPermissions(p=>e.target.checked?[...p,k]:p.filter(x=>x!==k))}/><span>{label}</span></label>)}</div><button className="secondary" disabled={busy} onClick={async()=>{setBusy(true);try{await api('/roles/'+role.code,{method:'PUT',body:{permissions}});success('تم تحديث صلاحيات الدور');}catch(e){setError(e.message);}finally{setBusy(false);}}}>حفظ الصلاحيات</button></section>;}
function Reports(){const {data,error}=useData('/reports');const [tab,setTab]=useState('people'),[department,setDepartment]=useState(''),[from,setFrom]=useState(''),[to,setTo]=useState('');if(error)return <ErrorBox error={error}/>;if(!data)return <Loading/>;const people=data.people.filter(p=>!department||p.department===department);const ids=new Set(people.map(p=>p.id));const leaves=data.leaves.filter(l=>ids.has(l.employee_id)&&(!from||l.start_date.slice(0,10)>=from)&&(!to||l.start_date.slice(0,10)<=to));const docs=data.documents.filter(d=>ids.has(d.employee_id));const missing=people.flatMap(p=>['IDENTITY','RESIDENCE','CLEARANCE'].filter(k=>!docs.some(d=>d.employee_id===p.id&&d.kind===k&&d.status==='APPROVED')).map(k=>({id:`${p.id}-${k}`,name:p.name,kind_label:docKinds[k],department:p.department})));const records=data.records.filter(r=>ids.has(r.employee_id)&&(!from||r.date.slice(0,10)>=from)&&(!to||r.date.slice(0,10)<=to)).map(r=>({...r,kind_label:recordKinds[r.kind],date:fmt(r.date)}));const balance=people.map(p=>({...p,remaining:p.entitlement-p.used}));const reports={people:{label:'الموظفون والأرصدة',rows:balance,columns:[['employee_no','الرقم'],['name','الاسم'],['department','القسم'],['entitlement','الاستحقاق'],['used','المستخدم'],['remaining','المتبقي']]},leaves:{label:'الإجازات',rows:leaves.map(l=>({...l,status_label:statuses[l.status],start:fmt(l.start_date),end:fmt(l.end_date)})),columns:[['employee','الموظف'],['type_label','النوع'],['start','من'],['end','إلى'],['days','الأيام'],['status_label','الحالة']]},documents:{label:'المستمسكات المنتهية والقريبة',rows:docs.filter(d=>d.expires_on&&new Date(d.expires_on)<new Date(Date.now()+30*86400000)&&d.status!=='REJECTED').map(d=>({...d,kind_label:docKinds[d.kind],expiry:fmt(d.expires_on)})),columns:[['employee','الموظف'],['kind_label','المستمسك'],['expiry','الانتهاء']]},missing:{label:'المستمسكات الناقصة',rows:missing,columns:[['name','الموظف'],['department','القسم'],['kind_label','المستمسك غير المعتمد']]},records:{label:'الدورات والتكريم',rows:records,columns:[['employee','الموظف'],['kind_label','النوع'],['title','العنوان'],['issuer','الجهة'],['date','التاريخ']]}};const r=reports[tab];return <><Header title="التقارير" subtitle="تقارير ضمن نطاق صلاحياتك، جاهزة للطباعة والتصدير"><button className="secondary" onClick={()=>window.print()}><Printer size={17}/>طباعة / PDF</button><button className="primary" onClick={()=>downloadCsv(r.label,r.columns,r.rows)}><Download size={17}/>تصدير CSV</button></Header><div className="tabs">{Object.entries(reports).filter(([k])=>data.canSeeDocuments||!['documents','missing'].includes(k)).map(([k,v])=><button key={k} className={tab===k?'selected':''} onClick={()=>setTab(k)}>{v.label}</button>)}</div><section className="panel"><div className="toolbar"><Select label="القسم" value={department} onChange={e=>setDepartment(e.target.value)} options={[["","جميع الأقسام"],...[...new Set(data.people.map(p=>p.department))].map(x=>[x,x])]}/>{['leaves','records'].includes(tab)&&<><Input label="من تاريخ" type="date" value={from} onChange={e=>setFrom(e.target.value)}/><Input label="إلى تاريخ" type="date" value={to} onChange={e=>setTo(e.target.value)}/></>}<span className="muted">{num(r.rows.length)} سجل</span></div><div className="print-heading"><h2>{r.label}</h2><p>{fmt(today())} · {department||'جميع الأقسام'}</p></div><Table rows={r.rows} columns={r.columns}/></section><p className="muted report-note">الاستحقاق التجريبي 30 يومًا سنويًا. الجواز وإجازة السوق اختياريان، ولا يُحسبان ضمن المستمسكات الناقصة.</p></>;}
function Audit(){const {data,error}=useData('/audit');const [filter,setFilter]=useState('');if(error)return <ErrorBox error={error}/>;if(!data)return <Loading/>;const labels={LOGIN:'تسجيل دخول',CREATE:'إضافة',UPDATE:'تعديل',SUBMIT:'تقديم طلب',APPROVE:'اعتماد',REJECT:'رفض',CANCEL:'إلغاء',UPLOAD:'رفع مستمسك',VIEW_FILE:'عرض ملف'};const entities={user:'مستخدم',employee:'موظف',leave:'إجازة',role:'دور',document:'مستمسك',record:'سجل تطوير',profile_change:'بيانات شخصية',leave_balance:'رصيد إجازة',department:'قسم',employee_photo:'صورة شخصية'};return <><Header title="سجل التدقيق" subtitle="آخر 300 عملية · سجل للقراءة فقط"/><section className="panel"><div className="toolbar"><div className="search"><Search size={18}/><input aria-label="البحث في سجل التدقيق" placeholder="ابحث باسم المستخدم أو العملية" value={filter} onChange={e=>setFilter(e.target.value)}/></div></div><Table rows={data.filter(r=>(r.actor+' '+(labels[r.action]||r.action)).includes(filter))} columns={[["id","الرقم"],["actor","المستخدم"],['action','العملية',r=>labels[r.action]||r.action],['entity','السجل',r=>`${entities[r.entity]||r.entity} #${r.entity_id}`],['created_at','التوقيت',r=>formatDateTime(r.created_at)],['details','التغييرات',r=>r.before_data||r.after_data?<details><summary>عرض</summary><pre dir="ltr">{JSON.stringify({before:r.before_data,after:r.after_data},null,2)}</pre></details>:'—']]}/></section></>;}
class ErrorBoundary extends React.Component{state={error:null};static getDerivedStateFromError(error){return {error};}render(){if(this.state.error)return <div className="fatal"><h1>تعذر عرض الصفحة</h1><p>أعد تحميل الصفحة وحاول مجددًا.</p><button className="primary" onClick={()=>location.reload()}>إعادة تحميل</button></div>;return this.props.children;}}
createRoot(document.getElementById('root')).render(<ErrorBoundary><App/></ErrorBoundary>);



